#![allow(unused_imports)]

/// A bitfield kept in bytes that no integer type fits (packed structs).
#[inline(always)]
pub(crate) fn bits_get(bytes: &[u8], shift: u32, width: u32) -> u32 {
    let mut v = 0u64;
    for (i, b) in bytes.iter().enumerate() {
        v |= (*b as u64) << (8 * i);
    }
    ((v >> shift) & ((1u64 << width) - 1)) as u32
}

#[inline(always)]
pub(crate) fn bits_set(bytes: &mut [u8], shift: u32, width: u32, value: u32) {
    let mut v = 0u64;
    for (i, b) in bytes.iter().enumerate() {
        v |= (*b as u64) << (8 * i);
    }
    let mask = ((1u64 << width) - 1) << shift;
    v = (v & !mask) | (((value as u64) << shift) & mask);
    for (i, b) in bytes.iter_mut().enumerate() {
        *b = (v >> (8 * i)) as u8;
    }
}

